<script setup lang="ts">
import { ref, computed } from 'vue'
import { applyCustomerSync } from '@/mocks/masterSync'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
import type { MasterDataDefinition } from '@/mocks/masterDataConfig'
import { p3, masterConfig, sourceExamples, syncingMasters, SYNC_TIME, type MasterP3 } from '@/mocks/phase3'
const systemFields=['LastModifiedDate','SystemModstamp']
const props=defineProps<{master:MasterDataDefinition}>(),{t}=useI18n(),syncVisible=ref(false),draft=ref<MasterP3>(),loadedFields=ref<string[]>([]),loadedFor=ref(''),fetching=ref(false)
const cfg=computed(()=>masterConfig(props.master.id)),source=computed(()=>sourceExamples.find(s=>s.name===draft.value?.source))
let fetchVersion=0
const sourceKey=computed(()=>JSON.stringify([draft.value?.connection,draft.value?.source]))
const fieldsCurrent=computed(()=>loadedFor.value===sourceKey.value&&loadedFields.value.length>0)
function openSync(){fetchVersion++;fetching.value=false;draft.value=JSON.parse(JSON.stringify(cfg.value));if(draft.value)for(const [field,value] of Object.entries(draft.value.fields))draft.value.fields[field]=props.master.columns.find(c=>c.id===value||c.label===value)?.id||'';loadedFields.value=[];loadedFor.value='';syncVisible.value=true}
const emit=defineEmits<{history:[]}>()
function changeSource(){fetchVersion++;fetching.value=false}
function changeConnection(){if(draft.value)draft.value.source='';changeSource()}
function closeSync(){fetchVersion++;fetching.value=false}
async function fetchFields(){if(!draft.value?.connection||!source.value||fetching.value)return;const version=++fetchVersion,key=sourceKey.value,fields=[...source.value.fields],sameSaved=draft.value.connection===cfg.value.connection&&draft.value.source===cfg.value.source,previous=loadedFor.value===key||sameSaved?{...draft.value.fields}:{};fetching.value=true;await new Promise(r=>setTimeout(r,1000));if(version!==fetchVersion||sourceKey.value!==key)return;draft.value.fields=Object.fromEntries(fields.filter(f=>!systemFields.includes(f)).map(f=>[f,previous[f]||(f==='Id'?'':props.master.columns.find(c=>c.label===f)?.id)||'']));loadedFields.value=fields;loadedFor.value=key;fetching.value=false}

function saveSync(){const d=draft.value;if(!d||!d.connection||!d.source||!fieldsCurrent.value){ElMessage.warning(t('phase3.fetchFieldsFirst'));return}const values=Object.values(d.fields).filter(Boolean);if(!values.length||values.some(v=>!props.master.columns.some(c=>c.id===v))||new Set(values).size!==values.length){ElMessage.warning(t('phase3.mappingInvalid'));return}Object.assign(cfg.value,{connection:d.connection,source:d.source,fields:d.fields,automatic:true,schedule:{frequency:'daily',time:SYNC_TIME,weekday:1,month:1,day:1}});syncVisible.value=false;ElMessage.success(t('phase3.saved'))}
async function updateNow(){const id=props.master.id,master=props.master,c=masterConfig(id);if(!c.enabled||!c.connection||!c.source||syncingMasters[id])return;syncingMasters[id]=true;const run={id:crypto.randomUUID(),start:new Date().toLocaleString('ja-JP'),duration:'—',trigger:'manual',status:'syncing',added:0,changed:0,removed:0,unchanged:0,failed:0,reason:''};c.history.unshift(run);const started=Date.now();try{await new Promise(r=>setTimeout(r,1800));const result=c.history.find(r=>r.id===run.id)!;const counts=id==='master-disease'&&c.connection==='sfdc'&&c.source==='ICD10コードマスタ'?applyCustomerSync(master,{...c.fields}):{added:0,changed:0,unchanged:master.rows.length};Object.assign(result,{...counts,status:'success',duration:`${((Date.now()-started)/1000).toFixed(1)}s`});ElMessage.success(t('phase3.mockSyncSuccess'))}catch(error){const result=c.history.find(r=>r.id===run.id);const reason=error instanceof Error&&error.message==='emptySource'?t('phase3.emptySource'):error instanceof Error&&error.message==='capacityExceeded'?t('phase3.syncCapacityExceeded'):error instanceof Error&&error.message==='invalidSourceId'?t('phase3.syncInvalidSourceId'):t('phase3.connectionFailed');if(result)Object.assign(result,{status:'failed',reason,duration:`${((Date.now()-started)/1000).toFixed(1)}s`});ElMessage.error(reason)}finally{syncingMasters[id]=false}}
defineExpose({openSync,openHistory:()=>emit('history'),updateNow})
</script>
<template><el-dialog v-model="syncVisible" :title="t('phase3.sync')" width="840px" destroy-on-close @closed="closeSync"><el-form v-if="draft" label-position="top" class="p3-sync-form"><div class="p3-source-row"><el-form-item :label="t('phase3.connection')" required><el-select v-model="draft.connection" @change="changeConnection"><el-option v-for="c in p3.connections" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-form-item :label="t('phase3.source')" required><el-select v-model="draft.source" :disabled="!draft.connection" @change="changeSource"><el-option v-for="s in sourceExamples" :key="s.name" :value="s.name" :label="s.name"/></el-select></el-form-item><el-button :disabled="!draft.connection||!draft.source" :loading="fetching" @click="fetchFields">{{t('phase3.fetchFields')}}</el-button></div><div class="p3-fixed-schedule">{{t('phase3.fixedSchedule')}}</div><el-table v-if="loadedFields.length" v-loading="fetching" :data="loadedFields" border><el-table-column :label="t('phase3.sourceField')"><template #default="{row}">{{row}}</template></el-table-column><el-table-column :label="t('phase3.targetColumn')"><template #default="{row}"><span v-if="systemFields.includes(row)" class="p3-system-field">{{t('phase3.systemManagedField')}}</span><el-select v-else v-model="draft.fields[row]" :disabled="!fieldsCurrent||fetching" clearable :placeholder="t('phase3.noMapping')"><el-option v-for="column in master.columns" :key="column.id" :value="column.id" :label="column.label" :disabled="Object.entries(draft.fields).some(([source,target])=>source!==row&&target===column.id)"/></el-select></template></el-table-column></el-table><el-empty v-else v-loading="fetching" :description="t('phase3.fetchFieldsFirst')" :image-size="64"/></el-form><template #footer><el-button @click="syncVisible=false">{{t('phase3.cancel')}}</el-button><el-button type="primary" :disabled="!fieldsCurrent||fetching" @click="saveSync">{{t('phase3.save')}}</el-button></template></el-dialog></template>
<style scoped>.p3-source-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:16px;align-items:end}.p3-source-row .el-form-item{margin-bottom:0}.p3-source-row>.el-button{margin:0}.el-select{width:100%}.p3-fixed-schedule{margin:14px 0 20px;font-size:15px;color:var(--el-text-color-secondary)}</style>
